<script setup lang="ts">
import { computed, nextTick, ref } from 'vue'
import { Monitor, MonitorPlay, Plus, Search, Eye, Settings2, Trash2, Wifi, WifiOff, Volume2, VolumeX, X, Save, Check, ExternalLink, Copy, RefreshCw, LayoutDashboard, ShieldCheck } from 'lucide-vue-next'

type Screen = { id: number; name: string; zone: string; floor: string; rooms: string[]; online: boolean; sound: boolean; theme: 'dark' | 'light'; language: 'uz' | 'ru'; code: string; lastSeen: string }
const screens = ref<Screen[]>([
  { id: 1, name: 'Asosiy kutish zali', zone: 'Asosiy zal', floor: '1-qavat', rooms: ['101', '102', '103'], online: true, sound: true, theme: 'dark', language: 'uz', code: '483921', lastSeen: 'Hozir' },
  { id: 2, name: 'UZI kutish zali', zone: 'Diagnostika', floor: '2-qavat', rooms: ['201', '202'], online: true, sound: false, theme: 'dark', language: 'uz', code: '619284', lastSeen: 'Hozir' },
  { id: 3, name: 'Laboratoriya TV', zone: 'Laboratoriya', floor: '1-qavat', rooms: ['105'], online: false, sound: true, theme: 'light', language: 'ru', code: '728135', lastSeen: 'Bugun 09:41' },
])
const roomOptions = ['101', '102', '103', '104', '105', '106', '201', '202', '203']
const query = ref('')
const status = ref('all')
const openModal = ref(false)
const editingId = ref<number | null>(null)
const notice = ref('')
const form = ref({ name: '', zone: 'Asosiy zal', floor: '1-qavat', rooms: ['101'] as string[], sound: true, theme: 'dark' as 'dark' | 'light', language: 'uz' as 'uz' | 'ru' })
const shown = computed(() => screens.value.filter(s => (status.value === 'all' || (status.value === 'online') === s.online) && `${s.name} ${s.zone} ${s.floor} ${s.rooms.join(' ')}`.toLowerCase().includes(query.value.toLowerCase())))
const activeCount = computed(() => screens.value.filter(s => s.online).length)
const offlineCount = computed(() => screens.value.length - activeCount.value)
const selectedId=ref(1);
const selectedScreen=computed(()=>screens.value.find(s=>s.id===selectedId.value)||screens.value[0]);
const ticketFor=(s:Screen,offset=0)=>`J-${String(s.id+offset).padStart(3,'0')}`;
const roomFor=(s:Screen)=>s.rooms[0] || '—';
function toggleSound(s:Screen){s.sound=!s.sound;notice.value='Ovoz holati faqat lokal namoyishda o‘zgartirildi.';}
const previewScreen = ref<Screen | null>(null)
function addScreen() { editingId.value = null; form.value = { name: '', zone: 'Asosiy zal', floor: '1-qavat', rooms: ['101'], sound: true, theme: 'dark', language: 'uz' }; openModal.value = true }
function editScreen(s: Screen) { editingId.value = s.id; form.value = { name: s.name, zone: s.zone, floor: s.floor, rooms: [...s.rooms], sound: s.sound, theme: s.theme, language: s.language }; openModal.value = true }
function toggleRoom(room: string) { form.value.rooms = form.value.rooms.includes(room) ? form.value.rooms.filter(r => r !== room) : [...form.value.rooms, room] }
function saveScreen() {
  if (!form.value.name.trim() || form.value.rooms.length === 0) { notice.value = 'Tablo nomi va kamida bitta kabinetni kiriting.'; return }
  if (editingId.value !== null) {
    const s = screens.value.find(x => x.id === editingId.value)
    if (s) Object.assign(s, { ...form.value, rooms: [...form.value.rooms] })
  } else {
    const id = Math.max(0, ...screens.value.map(s => s.id)) + 1
    screens.value.unshift({ id, ...form.value, rooms: [...form.value.rooms], online: false, code: String(100000 + ((id * 73129) % 899999)).slice(0, 6), lastSeen: 'Ulanmagan' })
  }
  openModal.value = false
  notice.value = 'Tablo sozlamalari demo rejimda saqlandi.'
}
function deleteScreen(s: Screen) { if (confirm(`“${s.name}” tabloni o‘chirasizmi?`)) { screens.value = screens.value.filter(x => x.id !== s.id); notice.value = 'Tablo demo ro‘yxatdan o‘chirildi.' } }
function openPreview(s: Screen) { selectedId.value=s.id; previewScreen.value = s }
function copyCode(code: string) { if (navigator.clipboard?.writeText) navigator.clipboard.writeText(code).then(() => { notice.value = 'Ulanish kodi nusxalandi.' }).catch(() => { notice.value = `Ulanish kodi: ${code}` }); else notice.value = `Ulanish kodi: ${code}` }
const tvElement = ref<HTMLElement | null>(null)
async function fullScreenPreview() { if (!selectedScreen.value) return; previewScreen.value = selectedScreen.value ?? null; await nextTick(); if (tvElement.value?.requestFullscreen) await tvElement.value.requestFullscreen().catch(() => {}) }
</script>

<template>
  <section class="tb-page legacy-ui">
    <div class="tb-head">
      <div><div class="tb-eyebrow">
        <MonitorPlay :size="15" /> NAVBAT TIZIMI / EKRANLAR</div>
          <h1>Tablo boshqaruvi</h1><p>Kutish zali televizorlari, kabinetlar va elektron navbatni boshqarish</p></div>
      <div class="tb-head-buttons">
        <button class="tb-btn tb-soft" @click="$emit('open-navbatlar')">  ← Navbatlarga qaytish </button>
        <button class="tb-btn tb-soft" @click="fullScreenPreview" :disabled="!selectedScreen">
          <ExternalLink :size="17" /> TV ko‘rinishini ochish</button>
          <button class="tb-btn tb-primary" @click="addScreen">
            <Plus :size="19" /> Yangi tablo
          </button>
      </div>
    </div>

    <div v-if="notice" class="tb-notice" role="status"><ShieldCheck :size="17" /> {{ notice }} <button @click="notice = ''" aria-label="Yopish"><X :size="15" /></button></div>
    <div class="tb-metrics">
      <article class="tb-metric blue"><span class="tb-metric-icon"><Monitor :size="26" /></span><div><small>Jami tablolar</small><strong>{{ screens.length }}</strong><span>Klinikaga biriktirilgan</span></div></article>
      <article class="tb-metric green"><span class="tb-metric-icon"><Wifi :size="26" /></span><div><small>Onlayn tablolar</small><strong>{{ activeCount }}</strong><span>Namuna holati</span></div></article>
      <article class="tb-metric amber"><span class="tb-metric-icon"><WifiOff :size="26" /></span><div><small>Oflayn tablolar</small><strong>{{ offlineCount }}</strong><span>Namuna holati</span></div></article>
      <article class="tb-metric violet"><span class="tb-metric-icon"><LayoutDashboard :size="26" /></span><div><small>Biriktirilgan kabinetlar</small><strong>{{ new Set(screens.flatMap(s => s.rooms)).size }}</strong><span>Navbat ko‘rsatiladigan xonalar</span></div></article>
    </div>

    <div class="tb-layout">
      <div class="tb-panel tb-main-panel">
        <div class="tb-panel-heading"><div><h2>Ulangan ekranlar</h2><p>Har bir televizor uchun ko‘rsatiladigan kabinetlarni belgilang</p></div><span class="tb-counter">{{ shown.length }} ta ekran</span></div>
        <div class="tb-toolbar"><label class="tb-search"><Search :size="18" /><input v-model="query" placeholder="Tablo nomi, joylashuvi yoki kabinet..." /></label><select v-model="status" aria-label="Holati"><option value="all">Barcha holatlar</option><option value="online">Onlayn</option><option value="offline">Oflayn</option></select></div>
        <div class="tb-table-wrap"><table><thead><tr><th>Tablo / ekran</th><th>Joylashuv</th><th>Kabinetlar</th><th>Holati</th><th>Ovoz</th><th>Amallar</th></tr></thead><tbody>
          <tr v-for="s in shown" :key="s.id"><td><div class="tb-name"><span class="tb-device-icon"><Monitor :size="22" /></span><div><strong>{{ s.name }}</strong><small>TV-{{ String(s.id).padStart(3, '0') }} · {{ s.lastSeen }}</small></div></div></td><td><strong class="tb-normal">{{ s.zone }}</strong><small>{{ s.floor }}</small></td><td><div class="tb-room-tags"><span v-for="r in s.rooms" :key="r">{{ r }}</span></div></td><td><span class="tb-status" :class="s.online ? 'online' : 'offline'"><i></i>{{ s.online ? 'Onlayn' : 'Oflayn' }}</span></td><td><button class="tb-sound" :aria-label="s.name+' ovoz'" @click="toggleSound(s)" :class="{ muted: !s.sound }"><Volume2 v-if="s.sound" :size="17" /><VolumeX v-else :size="17" /> {{ s.sound ? 'Yoqilgan' : 'O‘chiq' }}</button></td><td><div class="tb-actions"><button title="Ko‘rish" @click="openPreview(s)"><Eye :size="17" /></button><button title="Sozlash" @click="editScreen(s)"><Settings2 :size="17" /></button><button title="O‘chirish" class="danger" @click="deleteScreen(s)"><Trash2 :size="17" /></button></div></td></tr>
          <tr v-if="!shown.length"><td colspan="6" class="tb-empty">Tanlangan filtrlar bo‘yicha tablo topilmadi.</td></tr>
        </tbody></table></div>
        <div class="tb-panel-footer"><span>TV biriktirish uchun ekrandagi kodni admin panelga kiriting.</span><button @click="addScreen"><Plus :size="16" /> Yangi ekran qo‘shish</button></div>
      </div>
      <aside class="tb-side">
        <div v-if="selectedScreen" class="tb-panel tb-preview-panel"><div class="tb-aside-title"><div><h2>Jonli ko‘rinish</h2><small>Kutish zalidagi televizor</small></div><button @click="openPreview(selectedScreen!)"><ExternalLink :size="16" /></button></div>
          <label class="tb-preview-selector">Preview ekrani<select v-model="selectedId" aria-label="Preview ekrani"><option v-for="s in screens" :key="s.id" :value="s.id">{{s.name}}</option></select></label><div class="tb-mini-tv"><div class="tb-mini-tv-top"><b>SHIFO MED</b><span>ELEKTRON NAVBAT</span></div><span class="tb-mini-caption">HOZIR CHAQIRILMOQDA</span><div class="tb-mini-main"><div><strong>{{ticketFor(selectedScreen!)}}</strong><span>NAVBAT</span></div><div><strong>{{roomFor(selectedScreen!)}}</strong><span>KABINET</span></div></div><div class="tb-mini-foot">Marhamat, qabulga kiring!</div></div>
          <button class="tb-wide-outline" @click="openPreview(selectedScreen!)"><Eye :size="17" /> Oldindan ko‘rish</button>
        </div>
        <div class="tb-panel tb-help"><h2><ShieldCheck :size="19" /> Xavfsiz ulash</h2><p>Har bir televizor alohida kod orqali ulanadi. Admin login-parolini televizorga kiritish shart emas.</p><div class="tb-help-steps"><div><span>1</span>TVda tablo sahifasini oching</div><div><span>2</span>6 xonali ulanish kodini oling</div><div><span>3</span>Filial va kabinetlarni biriktiring</div></div></div>
        <div class="tb-panel tb-help"><h2><RefreshCw :size="18" /> Demo rejim</h2><p>Hozirgi onlayn/oflayn holatlar va navbat ma’lumotlari namunaviy. Haqiqiy qurilma sinxronizatsiyasi API ulangandan keyin ishlaydi.</p></div>
      </aside>
    </div>

    <div v-if="openModal" class="tb-overlay" @click.self="openModal = false"><div class="tb-dialog" role="dialog" aria-modal="true" aria-label="Tablo sozlamalari"><header><div><h2>{{ editingId === null ? 'Yangi tablo qo‘shish' : 'Tabloni sozlash' }}</h2><p>Ekran joylashuvi va qaysi kabinetlarni ko‘rsatishini belgilang</p></div><button @click="openModal = false" aria-label="Yopish"><X :size="20" /></button></header><div class="tb-form"><div class="tb-form-grid"><label>Tablo nomi <input v-model="form.name" placeholder="Masalan, Asosiy kutish zali" maxlength="70" /></label><label>Kutish zali <select v-model="form.zone"><option>Asosiy zal</option><option>Diagnostika</option><option>Laboratoriya</option><option>VIP zal</option><option>Bolalar bo‘limi</option></select></label><label>Qavat <select v-model="form.floor"><option>1-qavat</option><option>2-qavat</option><option>3-qavat</option><option>4-qavat</option></select></label><label>Ekran dizayni <select v-model="form.theme"><option value="dark">To‘q (Dark)</option><option value="light">Yorug‘ (Light)</option></select></label><label>Til <select v-model="form.language"><option value="uz">O‘zbekcha</option><option value="ru">Русский</option></select></label><label class="tb-toggle-row">Ovozli e’lon <input v-model="form.sound" type="checkbox" /></label></div><div class="tb-room-field"><strong>Kabinetlarni tanlang</strong><p>Ushbu tablo ko‘rsatadigan xonalar</p><div class="tb-room-picker"><button v-for="r in roomOptions" :key="r" :class="{ selected: form.rooms.includes(r) }" @click="toggleRoom(r)">{{ r }} <Check v-if="form.rooms.includes(r)" :size="13" /></button></div></div></div><footer><button class="tb-btn tb-soft" @click="openModal = false">Bekor qilish</button><button class="tb-btn tb-primary" @click="saveScreen"><Save :size="16" /> Saqlash</button></footer></div></div>

    <div v-if="previewScreen" class="tb-overlay" @click.self="previewScreen = null"><div class="tb-dialog tb-preview-dialog" role="dialog" aria-modal="true" aria-label="Tablo ko‘rinishi"><header><div><h2>{{ previewScreen.name }}</h2><p>{{ previewScreen.floor }} · {{ previewScreen.rooms.join(', ') }}-kabinetlar</p></div><button @click="previewScreen = null" aria-label="Yopish"><X :size="20" /></button></header><div ref="tvElement" class="tb-big-tv" :class="previewScreen.theme"><div class="tb-big-tv-head"><b>SHIFO MED</b><span>ELEKTRON NAVBAT</span></div><p>HOZIR CHAQIRILMOQDA</p><div class="tb-big-tv-codes"><div><strong>{{ticketFor(previewScreen)}}</strong><small>NAVBAT RAQAMI</small></div><div><strong>{{ roomFor(previewScreen) }}</strong><small>KABINET</small></div></div><h2>Marhamat, qabulga kiring!</h2><div class="tb-big-next">KEYINGI NAMUNA NAVBAT: {{ticketFor(previewScreen,1)}} → {{ roomFor(previewScreen) }}</div></div><div class="tb-preview-bottom"><span>Ulanish kodi: <b>{{ previewScreen.code }}</b></span><button class="tb-btn tb-soft" @click="copyCode(previewScreen.code)"><Copy :size="16" /> Kodni nusxalash</button></div><p class="tb-preview-caveat">Bu demo ko‘rinish. Haqiqiy TV ulanishi va navbat sinxronizatsiyasi backend integratsiyasidan keyin ishlaydi.</p></div></div>
  </section>
</template>

